#!/usr/bin/env bash
# Reproducible Capacitor 7 iOS setup. Never starts an external build or upload.
set -euo pipefail

cd "$(dirname "$0")/.."

# Keep the sticker palette free of duplicate and invalid emoji before iOS build.
python3 scripts/test_emoji_stickers.py

# Include body-pose AI locally before Vite copies public/ assets.
python3 scripts/fetch_pose_model.py

if [ ! -d ios/App/App.xcodeproj ]; then
  # Native project may be generated by Codemagic from a clean Git checkout.
  # The CI preflight only uploads generated files as review artifacts.
  npm run build:native
  npx cap add ios
else
  npm run build:native
fi

# Fail closed if the complete local AI model, WASM and Japanese fonts
# cannot be included in this iOS app. No CDN request is needed at runtime.
python3 scripts/bundle_native_offline.py

npx cap sync ios

# Verify that Capacitor actually copied ALL resources into the .app web bundle.
python3 scripts/bundle_native_offline.py --out ios/App/App/public --verify-only

# Keep the generated Info.plist privacy descriptions and display name correct.
python3 - <<'PY'
import plistlib
from pathlib import Path
path = Path('ios/App/App/Info.plist')
with path.open('rb') as f:
    info = plistlib.load(f)
info['CFBundleDisplayName'] = 'JOMON PIX'
info['NSCameraUsageDescription'] = '写真を撮影してJOMON PIXで加工するために使用します。'
info['NSPhotoLibraryUsageDescription'] = '写真を選択してJOMON PIXで加工するために使用します。'
info['NSPhotoLibraryAddUsageDescription'] = '加工した写真を端末に保存するために使用します。'
info['UIFileSharingEnabled'] = True
info['LSSupportsOpeningDocumentsInPlace'] = True
info['ITSAppUsesNonExemptEncryption'] = False
# Xcode 27/iOS 27 kills apps using the legacy AppDelegate-only UI lifecycle.
# npx cap sync ios must never reset our UIWindowScene configuration.
# UIKit instantiates the existing CAPBridgeViewController using Main.storyboard.
info.pop('UIMainStoryboardFile', None)
info['UIApplicationSceneManifest'] = {
    'UIApplicationSupportsMultipleScenes': False,
    'UISceneConfigurations': {
        'UIWindowSceneSessionRoleApplication': [{
            'UISceneConfigurationName': 'Default Configuration',
            'UISceneDelegateClassName': '$(PRODUCT_MODULE_NAME).SceneDelegate',
            'UISceneStoryboardFile': 'Main',
        }],
    },
}
# iPhone and iPad editing controls are designed for portrait.
info['UISupportedInterfaceOrientations'] = ['UIInterfaceOrientationPortrait']
info['UISupportedInterfaceOrientations~ipad'] = ['UIInterfaceOrientationPortrait']
info['UIRequiresFullScreen'] = True
# The old 32-bit armv7 requirement is obsolete on iOS 15+.
info.pop('UIRequiredDeviceCapabilities', None)
with path.open('wb') as f:
    plistlib.dump(info, f)
PY

# Capacitor 7 supports iOS 15+, while the generated CocoaPods template
# can still start at 14.0. Align BOTH the Pods and Xcode targets to iOS 15.
# Read the app version from package.json rather than freezing it at 1.0.0.
python3 - <<'PY'
from pathlib import Path
import json
import re

app_version = json.loads(Path('package.json').read_text(encoding='utf-8')).get('version')
if not isinstance(app_version, str) or not re.fullmatch(r'[0-9]+\.[0-9]+\.[0-9]+', app_version):
    raise ValueError(f'Invalid package.json iOS marketing version: {app_version!r}')

podfile = Path('ios/App/Podfile')
pods = podfile.read_text()
pods, pod_count = re.subn(r"platform :ios, '[0-9.]+'", "platform :ios, '15.0'", pods)
if pod_count != 1:
    raise RuntimeError('Could not set iOS deployment target in Podfile')
podfile.write_text(pods)

project = Path('ios/App/App.xcodeproj/project.pbxproj')
text = project.read_text()
# Fix the escaped-linebreak form accidentally written by an earlier
# scaffold attempt; do not touch the legitimate \\n inside Xcode shell scripts.
for escaped, actual in [
    (r';\n/* End PBXBuildFile section */', ';\n/* End PBXBuildFile section */'),
    (r';\n/* End PBXFileReference section */', ';\n/* End PBXFileReference section */'),
    (r'/* Info.plist */,\n', '/* Info.plist */,\n'),
    (r'/* Main.storyboard in Resources */,\n',
     '/* Main.storyboard in Resources */,\n'),
]:
    text = text.replace(escaped, actual)
text, target_count = re.subn(
    r'IPHONEOS_DEPLOYMENT_TARGET = [0-9.]+;',
    'IPHONEOS_DEPLOYMENT_TARGET = 15.0;',
    text,
)
text, version_count = re.subn(
    r'MARKETING_VERSION = [0-9.]+;',
    f'MARKETING_VERSION = {app_version};',
    text,
)
if target_count < 2 or version_count < 2:
    raise RuntimeError('Could not set iOS target or marketing version')

# Simply writing an .xcprivacy file is not sufficient; it must be included
# in the Xcode target resources so it is copied into the built .app bundle.
build_id = 'F1A512EDFE00000000000001'
file_id = 'F1A512EDFE00000000000002'
if build_id not in text:
    entries = [
      (
        '/* End PBXBuildFile section */',
        '\t\t' + build_id + ' /* PrivacyInfo.xcprivacy in Resources */ = {isa = PBXBuildFile; fileRef = ' +
        file_id + ' /* PrivacyInfo.xcprivacy */; };\n/* End PBXBuildFile section */',
      ),
      (
        '/* End PBXFileReference section */',
        '\t\t' + file_id + ' /* PrivacyInfo.xcprivacy */ = {isa = PBXFileReference; lastKnownFileType = text.xml; path = PrivacyInfo.xcprivacy; sourceTree = "<group>"; };\n/* End PBXFileReference section */',
      ),
      (
        '504EC3131FED79650016851F /* Info.plist */,',
        '504EC3131FED79650016851F /* Info.plist */,\n\t\t\t\t' + file_id + ' /* PrivacyInfo.xcprivacy */,',
      ),
      (
        '504EC30D1FED79650016851F /* Main.storyboard in Resources */,',
        '504EC30D1FED79650016851F /* Main.storyboard in Resources */,\n\t\t\t\t' + build_id + ' /* PrivacyInfo.xcprivacy in Resources */,',
      ),
    ]
    for old, new in entries:
        if text.count(old) != 1:
            raise RuntimeError('Cannot attach privacy manifest to Xcode project: ' + old)
        text = text.replace(old, new)
project.write_text(text)
PY

python3 scripts/generate-ios-icon.py
# Validate that the six icon sources, native bridge, and Xcode setup agree.
python3 scripts/test_app_icon_switching.py
# Validate and package all six user-created alternate Home Screen icons.
python3 scripts/prepare_ios_icon_variants.py

# Apple requires a privacy manifest for native file timestamp access.
# Capacitor's Filesystem plugin uses this category for user-created files.
python3 - <<'PY'
from pathlib import Path
import plistlib
path = Path('ios/App/App/PrivacyInfo.xcprivacy')
privacy = {
    'NSPrivacyTracking': False,
    'NSPrivacyTrackingDomains': [],
    'NSPrivacyCollectedDataTypes': [],
    'NSPrivacyAccessedAPITypes': [{
        'NSPrivacyAccessedAPIType': 'NSPrivacyAccessedAPICategoryFileTimestamp',
        'NSPrivacyAccessedAPITypeReasons': ['C617.1'],
    }],
}
with path.open('wb') as f:
    plistlib.dump(privacy, f)
PY

echo "Prepared Capacitor iOS workspace: ios/App/App.xcworkspace"
echo "Web asset base: / (native bundle), bundle ID: com.jomonpix.app"
